  'files/playwright.config.ts':
    "import { defineConfig } from '@playwright/test';\n\n// Playwright and vitest default to the same globs, so each would try to run the\n// other's tests. Naming both directories is what keeps them apart.\nexport default defineConfig({\n  testDir: './e2e',\n  use: { baseURL: 'http://localhost:4173' },\n  webServer: {\n    command: 'bun run build && bun run start',\n    url: 'http://localhost:4173',\n    reuseExistingServer: true,\n  },\n});\n",
  'files/probity.config.ts':
    "import { defineConfig, enforceTdd } from '@nizos/probity';\n\nexport default defineConfig({\n  rules: [\n    {\n      files: ['src/**/model/**', 'src/**/lib/**', '!**/*.test.*', '!**/*.test-d.*', '!**/*.gen.*'],\n      rules: [enforceTdd()],\n    },\n  ],\n});\n",
  'files/skills-lock.json':
    '{\n  "version": 1,\n  "skills": {\n    "find-skills": {\n      "source": "vercel-labs/skills",\n      "sourceType": "github",\n      "skillPath": "skills/find-skills/SKILL.md",\n      "computedHash": "b146008599c31057cef1c145774cea5d5afb30e8f43fa802e47a4b461419aaaf"\n    },\n    "vitest": {\n      "source": "antfu/skills",\n      "sourceType": "github",\n      "skillPath": "skills/vitest/SKILL.md",\n      "computedHash": "943d436114c677802426741980146c07560bf375297666b03062444f4b98a785"\n    }\n  }\n}\n',
  'files/source/chromatic/harness.ts':
    "// Chromatic extends Playwright's test and expect rather than reading its\n// output, so an archive only exists for a spec that reaches for theirs.\nexport { expect, test } from '@chromatic-com/playwright';\n",
  'files/source/e2e/greeting.spec.ts':
    "import { expectAccessible } from './helpers/a11y.ts';\nimport { expect, test } from './helpers/harness.ts';\n\ntest('the home page greets whoever it was told to', async ({ page }) => {\n  await page.goto('/');\n\n  await expect(page.getByTestId('greeting')).toHaveText('hello world');\n  await expectAccessible(page);\n});\n",
  'files/source/e2e/helpers/a11y.ts':
    "import AxeBuilder from '@axe-core/playwright';\nimport { expect, type Page } from '@playwright/test';\n\n// A page nobody can operate is a page that does not work. These are the levels\n// a public site is held to, and a violation is a defect rather than a note.\nconst WCAG = ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa'] as const;\n\nexport async function expectAccessible(page: Page): Promise<void> {\n  const found = await new AxeBuilder({ page }).withTags([...WCAG]).analyze();\n\n  expect(found.violations).toStrictEqual([]);\n}\n",
  'files/source/e2e/helpers/harness.ts':
    "// Every spec reaches for its test and expect here, so a tool that extends them\n// is enabled by replacing this one file rather than every spec that exists.\nexport { expect, test } from '@playwright/test';\n",
  'files/source/greeting/index.ts': "export { GreetingPanel } from './ui/greeting-panel.tsx';\n",
  'files/source/greeting/model/greeting.property.test.ts':
    "import fc from 'fast-check';\nimport { describe, expect, it } from 'vitest';\n\nimport { greeting } from './greeting.ts';\n\ndescribe('what a greeting always does', () => {\n  it('opens with hello whatever it was given', () => {\n    fc.assert(\n      fc.property(fc.option(fc.string(), { nil: undefined }), (who) => {\n        expect(greeting(who)).toMatch(/^hello /u);\n      }),\n    );\n  });\n\n  it('carries the name whenever the name has something in it', () => {\n    fc.assert(\n      fc.property(\n        fc.string().filter((who) => who.trim() !== ''),\n        (who) => {\n          expect(greeting(who)).toContain(who.trim());\n        },\n      ),\n    );\n  });\n});\n",
  'files/source/greeting/model/greeting.test.ts':
    "import { describe, expect, it } from 'vitest';\n\nimport { greeting } from './greeting.ts';\n\ndescribe('greeting somebody', () => {\n  it('greets the name it was given', () => {\n    expect(greeting('ada')).toBe('hello ada');\n  });\n\n  it('greets the world when nobody was named', () => {\n    expect(greeting(undefined)).toBe('hello world');\n  });\n\n  it('greets the world when the name is only spaces', () => {\n    expect(greeting('   ')).toBe('hello world');\n  });\n\n  it('drops the spaces around a name', () => {\n    expect(greeting('  ada  ')).toBe('hello ada');\n  });\n});\n",
  'files/source/greeting/model/greeting.ts':
    "const STRANGER = 'world';\n\nexport function greeting(who: string | undefined): string {\n  const named = who?.trim() ?? '';\n\n  return `hello ${named === '' ? STRANGER : named}`;\n}\n",
  'files/source/greeting/ui/greeting-panel.tsx':
    'import { greeting } from \'../model/greeting.ts\';\n\nexport function GreetingPanel({ who }: { who?: string }) {\n  return <p data-testid="greeting">{greeting(who)}</p>;\n}\n',
  'files/source/routeTree.gen.ts':
    "/* eslint-disable */\n\n// @ts-nocheck\n\n// noinspection JSUnusedGlobalSymbols\n\n// This file was automatically generated by TanStack Router.\n// You should NOT make any changes in this file as it will be overwritten.\n// Additionally, you should also exclude this file from your linter and/or formatter to prevent it from being checked or modified.\n\nimport { Route as rootRouteImport } from './routes/__root'\nimport { Route as IndexRouteImport } from './routes/index'\n\nconst IndexRoute = IndexRouteImport.update({\n  id: '/',\n  path: '/',\n  getParentRoute: () => rootRouteImport,\n} as any)\n\nexport interface FileRoutesByFullPath {\n  '/': typeof IndexRoute\n}\nexport interface FileRoutesByTo {\n  '/': typeof IndexRoute\n}\nexport interface FileRoutesById {\n  __root__: typeof rootRouteImport\n  '/': typeof IndexRoute\n}\nexport interface FileRouteTypes {\n  fileRoutesByFullPath: FileRoutesByFullPath\n  fullPaths: '/'\n  fileRoutesByTo: FileRoutesByTo\n  to: '/'\n  id: '__root__' | '/'\n  fileRoutesById: FileRoutesById\n}\nexport interface RootRouteChildren {\n  IndexRoute: typeof IndexRoute\n}\n\ndeclare module '@tanstack/react-router' {\n  interface FileRoutesByPath {\n    '/': {\n      id: '/'\n      path: '/'\n      fullPath: '/'\n      preLoaderRoute: typeof IndexRouteImport\n      parentRoute: typeof rootRouteImport\n    }\n  }\n}\n\nconst rootRouteChildren: RootRouteChildren = {\n  IndexRoute: IndexRoute,\n}\nexport const routeTree = rootRouteImport\n  ._addFileChildren(rootRouteChildren)\n  ._addFileTypes<FileRouteTypes>()\n\nimport type { getRouter } from './router.tsx'\nimport type { createStart } from '@tanstack/react-start'\ndeclare module '@tanstack/react-start' {\n  interface Register {\n    ssr: true\n    router: Awaited<ReturnType<typeof getRouter>>\n  }\n}\n",
  'files/source/router.tsx':
    "import { createRouter } from '@tanstack/react-router';\n\nimport { routeTree } from './routeTree.gen';\n\nexport function getRouter() {\n  return createRouter({ routeTree, scrollRestoration: true });\n}\n",
  'files/source/routes/__root.tsx':
    "import { createRootRoute, HeadContent, Outlet, Scripts } from '@tanstack/react-router';\n\nexport const Route = createRootRoute({\n  head: () => ({\n    meta: [\n      { charSet: 'utf-8' },\n      { name: 'viewport', content: 'width=device-width, initial-scale=1' },\n      { title: '__PROJECT_NAME__' },\n    ],\n  }),\n  shellComponent: ({ children }) => (\n    <html lang=\"en\">\n      <head>\n        <HeadContent />\n      </head>\n      <body>\n        {children}\n        <Scripts />\n      </body>\n    </html>\n  ),\n  component: Outlet,\n});\n",
  'files/source/routes/index.tsx':
    "import { createFileRoute } from '@tanstack/react-router';\n\nimport { GreetingPanel } from '../../entities/greeting';\n\nexport const Route = createFileRoute('/')({ component: Home });\n\nfunction Home() {\n  return (\n    <main>\n      <h1>ket</h1>\n      <GreetingPanel who=\"world\" />\n    </main>\n  );\n}\n",
